diff --git a/validator-cli/.env.dist b/validator-cli/.env.dist
index 20b85bc..028c295 100644
--- a/validator-cli/.env.dist
+++ b/validator-cli/.env.dist
@@ -1,25 +1,39 @@
+# Signing key for the validator. Validated at startup: must be a 32-byte hex
+# private key. Only the address it derives to is ever logged.
 PRIVATE_KEY=

-# Networks: devnet, testnet, mainnet
+# Networks to watch. Must be non-empty and drawn from: devnet, testnet.
+# Left empty the bot starts, reports itself healthy, and watches nothing.
 NETWORKS=devnet,testnet

+# Outbox chains to watch. Must be non-empty and drawn from the configured
+# bridges: 11155111 (Sepolia), 10200 (Chiado).
+VEAOUTBOX_CHAINS=11155111

 # RPCs
 # Each RPC accepts a comma-separated list of endpoints. The first is primary; the rest are
 # used as automatic fallbacks (in order) whenever a request to the active endpoint fails.
+# Startup preflight calls eth_chainId on each and refuses to run if an endpoint
+# answers as a different chain than the route expects.
+#
+# RPC_ARB    - Arbitrum Sepolia (421614), the inbox for every route
+# RPC_ETH    - Sepolia (11155111): outbox for 11155111, router for 10200
+# RPC_GNOSIS - Chiado (10200): outbox for 10200
 RPC_ARB=https://sepolia-rollup.arbitrum.io/rpc
 RPC_ETH=
 RPC_GNOSIS=https://rpc.chiadochain.net

-
-GNOSIS_AMB_ADDRESS=0x8448E15d0e706C0298dECA99F0b4744030e59d7d
-
-VEAOUTBOX_CHAINS=11155111,421611
-
 # GraphQL endpoint of the merged `envio-indexer`: it indexes the inbox (ArbSepolia)
 # and both outboxes (Sepolia, Chiado) into a single endpoint.
 # Local dev: "http://localhost:8080/v1/graphql". Hosted: the indexer's HyperIndex GraphQL URL.
 ENVIO_URL=http://localhost:8080/v1/graphql

+# Deposit token for the Chiado route. Required whenever VEAOUTBOX_CHAINS includes 10200.
 GNOSIS_WETH=0x8d74e5e4DA11629537C4575cB0f33b4F0Dfa42EB

+# Optional. Must be https if set - the heartbeat is only ever sent over https,
+# so an http:// URL would silently never send.
+HEARTBEAT_URL=
+
+# Optional. Ships logs to Logtail when set; otherwise logs are pretty-printed locally.
+LOGTAIL_TOKEN=
diff --git a/validator-cli/README.md b/validator-cli/README.md
index ca75913..6d79ec4 100644
--- a/validator-cli/README.md
+++ b/validator-cli/README.md
@@ -6,10 +6,21 @@ A collection of bots for the Vea challenger and bridger ecosystem.

 # docker

-`docker compose build validator`
+Create the env file first — both compose files declare it as required, so they
+fail immediately without it. From the repo root:
+
+`cp validator-cli/.env.dist validator-cli/.env`
+
+Run the image published to GHCR (from the repo root):

 `docker compose up validator`

+Or build it from this working tree instead:
+
+`docker compose -f docker-compose.build.yml build validator`
+
+`docker compose -f docker-compose.build.yml up validator`
+
 By default, the validator performs two core functions:

 - Bridger: Saves snapshots, submits stored snapshots to the fast bridge receiver.
@@ -17,17 +28,28 @@ By default, the validator performs two core functions:

 # flags

-Update Dockerfile for passing different flags
+Flags are passed as the container's command. Set them on the `validator` service
+in whichever compose file you use — `docker-compose.yml` for the published image,
+`docker-compose.build.yml` when building from source:
+
+`command: yarn start --saveSnapshot --path=challenger`
+
+Both compose files set `command:`, which replaces the image's `CMD`, so editing
+`CMD` in `validator-cli/Dockerfile` has no effect when starting via compose; it
+applies only to a direct `docker run`. Outside Docker, append the flags to
+`yarn start`.

 `--saveSnapshot`

 Enables snapshot saving on the inbox when the bot observes a valid state.

-`--path=challenger | bridger | both`
+`--path=claimer | challenger | both`

+- claimer: Only submit snapshots — this is the "Bridger" role described above
 - challenger: Only challenge invalid claims
-- bridger: Only submit snapshots
-- both: Default mode, acts as both challenger and bridger
+- both: Default mode, acts as both claimer and challenger
+
+The accepted value is `claimer`, not `bridger`; `--path=bridger` throws `InvalidBotPathError`.

 # testing

